// Real LEVÉ Mobilidade logo, embedded as a base64 PNG data URI.
// Used both by the on-screen preview (Seal.tsx) and by the PDF export
// (generatePdf.ts), so the printed seal always matches the official logo
// (source: logo.jpg, trimmed and upscaled for print quality).
export const LEVE_LOGO_BASE64 = "data:image/png;base64,";

// Natural aspect ratio of the logo image (width / height), used to size
// it correctly wherever it's rendered without distortion.
export const LEVE_LOGO_ASPECT_RATIO = 532 / 324;

// White (monochrome) version of the LEVÉ Mobilidade logo, with a
// transparent background. Used on dark backgrounds — e.g. the app header —
// where the full-color logo (dark blue "MOBILIDADE" text) would lose
// contrast and become unreadable.
export const LEVE_LOGO_WHITE_BASE64 = "data:image/png;base64,";

// Natural aspect ratio of the white logo variant (width / height).
export const LEVE_LOGO_WHITE_ASPECT_RATIO = 766 / 454;
